<?phpinclude_once('edit_this.php');ini_set('display_errors', '1');ini_set('display_startup_errors', '1');error_reporting(E_ALL);date_default_timezone_set($SiteTimeZone);$TodayYmd=date('Ymd');$Now=date('Y-m-d H:i:s');$AmericanDateAndTime=date('m-d-Y').' at '.date('g:i:sa');//echo '$TodayYmd='.$TodayYmd.'<br>';//echo '$Now='.$Now.'<br>';//Get all variables passed to the pageif(isset($_REQUEST)){  foreach($_REQUEST as $key => $value) {    if(isset($view_all_variables_passed) and $view_all_variables_passed<>''){      echo '_REQUEST $key='.$key.' - $value='.$value.'<br>';    }    $$key=$value;    //echo $$key.'='.$value.'<br>';    if($key=='page'){      $page=$value;    }  }}if(!isset($page)){  $page='';}function convert_bad_microsoft_characters($string){  $search = array("’",                  "‘",                  "“",                  "”",                  "–",                  "•",                  "—",                  "&",                  "…"                 );  $replace = array("'",                   "'",                   '"',                   '"',                   '-',                   '-',                   '-',                   'and',                   '...'                  );  return str_replace($search, $replace, $string);}function NextRecordNumber($database_connection,$This_CMS_Table){  $sql="select info_id        from ".$This_CMS_Table."    order by info_id desc       limit 1     ";  //RunAndShowIt($database_connection,$sql);  $gotdata=pg_Exec($database_connection,$sql);  if(pg_num_rows($gotdata)>0){    //Get the old data (should only be 1 record)    for($results_loop=0;$results_loop<pg_num_rows($gotdata);$results_loop=$results_loop+1) {      $getarow=pg_Fetch_Array($gotdata,$results_loop);      $next_record_number=($getarow['info_id']+1);    }  } else {    $next_record_number='100000001';  }  return $next_record_number;}      function InsertRecord( $database_connection                      ,$This_CMS_Table                      ,$insert_id                      ,$insert_type                      ,$insert_page                      ,$insert_title                      ,$insert_image                      ,$insert_location                      ,$insert_details                      ,$insert_time                      ,$insert_how_many_hours                      ,$insert_name                      ,$insert_phone                      ,$insert_email_link                      ,$insert_webpage_link                      ,$insert_webpage_link_title                      ,$insert_added_on                      ,$insert_added_by                     ){  //Later ... Block duplicates/reloads  if($insert_time==''){    $use_this_for_the_time="NULL";  } else {    $use_this_for_the_time=pg_escape_literal(trim(convert_bad_microsoft_characters($insert_time)));  }  $add_it="insert into ".$This_CMS_Table."                 (                   info_id                  ,info_type                  ,info_page                  ,info_title                  ,info_image                  ,info_location                  ,info_details                  ,info_time                  ,info_how_many_hours                  ,info_name                  ,info_phone                  ,info_email_link                  ,info_webpage_link                  ,info_webpage_link_title                  ,info_added_on                  ,info_added_by                 )               values                 (                   ".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_id)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_type)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_page)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_title)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_image)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_location)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_details)))."                  ,".$use_this_for_the_time."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_how_many_hours)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_name)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_phone)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_email_link)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_webpage_link)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_webpage_link_title)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_added_on)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_added_by)))."                 )                 ";  //echo "\n".'<pre>$add_it='.$add_it.'</pre><br>';  pg_Exec($database_connection,$add_it);  echo "\n".'<div class="success">Added '.str_replace("''","'",$insert_title).'</div>';}function InsertUser( $database_connection                    ,$This_CMS_Table                    ,$insert_id                    ,$insert_type                    ,$insert_title                    ,$insert_hide_it                    ,$insert_name                    ,$insert_phone                    ,$insert_email_link                    ,$insert_added_on                    ,$insert_added_by                   ){  if($insert_hide_it==''){    $insert_hide_it=$PasswordShortCode;  }  $add_it="insert into ".$This_CMS_Table."                 (                   info_id                  ,info_type                  ,info_title                  ,info_hide_it                  ,info_name                  ,info_phone                  ,info_email_link                  ,info_added_on                  ,info_added_by                 )               values                 (                   ".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_id)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_type)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_title)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_hide_it)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_name)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_phone)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_email_link)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_added_on)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($insert_added_by)))."                 )                 ";  //echo "\n".'<pre>$add_it='.$add_it.'</pre><br>';  pg_Exec($database_connection,$add_it);  //echo "\n".'<div class="success">Added '.str_replace("''","'",$insert_title).' - '.str_replace("''","'",$insert_name).'</div>';}function RemoveRecord( $database_connection                      ,$This_CMS_Table                      ,$info_id                      ,$info_removed_on                      ,$info_removed_by                     ){  $remove_it="update ".$This_CMS_Table."                 set info_removed_on = ".pg_escape_literal(trim(convert_bad_microsoft_characters($info_removed_on)))."                     ,info_removed_by = ".pg_escape_literal(trim(convert_bad_microsoft_characters($info_removed_by)))."               where info_id = ".pg_escape_literal(trim(convert_bad_microsoft_characters($info_id)))."             ";  //echo "\n".'$remove_it='.$remove_it.'<br>';  pg_Exec($database_connection,$remove_it);  echo '<div class="removed_record">Removed Record ('.$info_id.')</div>';}function EmailIt( $database_connection                           ,$This_Email_Tracker_Table                           ,$to                           ,$subject                           ,$message                           ,$headers                           ,$sent_on                           ,$sent_by                          ){  //Find all signups for this email address  $sql="select *          from ".$This_Email_Tracker_Table."         where lower(email_address) = ".pg_escape_literal(trim(convert_bad_microsoft_characters($to)))."               and email_message = ".pg_escape_literal(trim(convert_bad_microsoft_characters($message)))."       ";  //RunAndShowIt($database_connection,$sql);  $gotdata=pg_Exec($database_connection,$sql);  $list='';  if(pg_num_rows($gotdata)>0){    echo "\n".'<div>Message previously sent to '.$to.' - did not send it again</div>';  } else {    $add_it="insert into ".$This_Email_Tracker_Table."                 (                   email_address                  ,email_message                  ,email_sent_on                  ,email_sent_by                 )               values                 (                   ".pg_escape_literal(trim(convert_bad_microsoft_characters($to)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($message)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($sent_on)))."                  ,".pg_escape_literal(trim(convert_bad_microsoft_characters($sent_by)))."                 )                 ";    //echo "\n".'<pre>$add_it='.$add_it.'</pre><br>';    pg_Exec($database_connection,$add_it);    mail($to, $subject, $message, $headers);    if(stristr($subject,'breakin attempt')){      echo "\n".'<p>Breakin attempt email sent</p>';    } else {      echo "\n".'<p>Email sent to '.$to.'</p>';    }  }}function RunAndShowIt($database_connection,$sql) {  echo '<style>';  echo '.TheList table { table-layout: fixed; }';  echo '.TheList tr:nth-child(even) { background: #EFEFEF; }';  echo '.TheList tr:nth-child(odd) { background: #DEDEDE; }';  echo '.TheList tr:hover { background: #CDCDCD; }';  echo '.TheList td { padding:3px; border: 1px solid #343434; width:150px; color:#010101; }';  echo '.QueryBox { background: #cdcdcd; padding:10px; margin: 0px 10px 20px 10px; color:#010101; }';  echo '.InfoBox { background: #4c4c4c; padding:10px; margin-top:2px; color: #EFEFEF; }';  echo '</style>';  $QueryRunTime='';  $msc=0;  $msc = microtime(true);  $gotdata=pg_Exec($database_connection,$sql);  $msc = microtime(true)-$msc;  $QueryRunTime="\n".'<br>'.round($msc,3).' seconds';  $RunTimeInSeconds=round($msc,3);  if(!$gotdata) {    return("*Error* Unable to query");  }  echo '<div class="QueryBox">Query:<br><PRE>'.$sql.'</PRE>';  $row=0;  $numcols = pg_num_fields($gotdata);  echo "\n".'<div class="InfoBox">Rows found: '.pg_num_rows($gotdata).'<br>Columns found: '.$numcols;  echo "\n".$QueryRunTime;  echo "\n".'</div>'."\n";  echo "\n".'<table class="TheList">';  echo "\n".'<tr>';  echo "\n".'<td style="vertical-align: bottom;">row</td>';  for($cols=0; $cols < pg_num_fields($gotdata) ; $cols++) {    $fieldname=pg_field_name($gotdata,$cols);    $fieldtype=pg_field_type($gotdata,$cols);    echo "\n".'<td>'.$fieldname.'<br>'.$fieldtype.'</td>';  }  echo "\n".'</tr>';  while($row<pg_num_rows($gotdata)){    $getarow = pg_Fetch_Row($gotdata,$row);    echo "\n".'<tr>';    echo "\n".'<td align="right">'.($row+1).'</td>';    for($col= 0; $col < $numcols;$col++) {      echo "\n".'<td><pre>';      if(trim($getarow[$col])<>"") {        echo $getarow[$col];      } else {        echo '&nbsp;';      }      echo '</pre></td>';    }    echo "\n".'</tr>';    $row=$row+1;  }  echo "\n".'</table>';  echo "\n".'</div>';  pg_free_result ($gotdata);  return("OK");}?>